  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "动机、测量计划各分量、请求身份、事件边界、单位和状态含义均有展开；能够区分工具响应、模型 token、业务完成与物理排空。",
      "evidence": [
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "$M=(c,e,w,s,b,i,a,r)$。"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "它们表示已经完成了什么准备，不表示系统一定达到物理稳态。"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "客户端收到的 chunk 数不等于模型生成的 token 数。"
        }
      ]
    },
    "legality": {
      "assessment": "partial",
      "reason": "任务、负载、状态、采集和分母的可比性条件充分，来源适用范围也有声明；但配对 t 区间将独立同分布和无 carryover 写成充分条件，遗漏小样本正态性或有效近似条件。16 区组的代数正确不能补足区间覆盖率前提。",
      "evidence": [
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "可比较性要求除被研究的处理外，测量对象相同或已按设计随机化。"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "在独立区组、差值近似独立同分布且无 carryover 的条件下，平均差值的区间可写成"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "伪代码贯通身份校验、预热覆盖、测量、窗口冻结、排空和独立确认，并保存失败与物理责任；但冷启动分支在建立实例后才开启窗口，没有把正文要求计入的首次加载连接到冷启动估计量。",
      "evidence": [
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "1 建立候选实例和状态记录；置 COLD；保留环境与版本身份"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "3 置 READY；检查队列基线、缓存状态、采集配置和时钟起点"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "业务完成与物理排空分别保存"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "在声明的测量方法范围内，解释了准备、采集计算、日志与内存访问、连接和序列化、replay 保存恢复及主机传输、同步和驻留成本。时间项采用同一墙钟域，明确关键路径和重叠去重；容量按唯一物理对象计算。冷启动成本未进入算法输出的问题另列算法缺口。",
      "evidence": [
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "$T_{run}=T_{setup}+T_{warm}+T_{measure}+T_{drain}+T_{export}$。"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "只有位于关键路径上的部分才增加墙钟，重叠工作不能重复相加。"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "唯一物理对象只计一次，日志字节数约为事件数乘每条记录大小，压缩和索引另计。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "说明改变 batch、缓存状态、采集方式、随机性设置和重复层级后应重新建立哪些条件；持续漂移、carryover 和确认区间跨阈值时，分别要求调整设计、隔离状态或保留未决。没有把局部算例外推为设备收益。",
      "evidence": [
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "共享缓存无法隔离时，应使用独立实例或显式重置，并在结果中声明共享状态。"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "若系统持续漂移，正确做法是报告漂移和条件，而不是挑一段最快区间称为稳态。"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "若区间跨过最小有意义效果，证据未定；应增加有效重复或报告未区分"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "竞争解释均连接了干预、观测与可反驳预测，覆盖冷路径、缓存继承、工具扰动、搜索偏差、输出工作量和队列增长；明确要求预测失败时修改机制解释，并限定同步干预的归因能力。",
      "evidence": [
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "独立实例或显式重置后差异消失，支持 carryover 解释。"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "若总时间改善而预测没有出现，应修改机制解释，即使候选本身仍可保留。"
        },
        {
          "path": "knowledge/workloads/measurement-comparability.md",
          "quote": "一次全设备同步使异常消失，同时改变多项关系，不能唯一定位缺哪条边。"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-WORK-004-R1-COLD-WINDOW",
      "criterion": "algorithm",
      "evidence": "正文要求“研究冷启动时，目标路径的首次加载、编译、autotune、图捕获和缓存填充必须计入”；RunOneArm 却先执行“1 建立候选实例和状态记录；置 COLD；保留环境与版本身份”，随后才“记录窗口起点；不得把 READY 前的请求计入测量窗口”。冷启动分支只禁止 warmup，未记录实例建立的计时边界，也未将其成本并入冷启动估计量。",
      "impact": "建立实例时发生的首次加载可以全部落在目标窗口之外。例如加载 10 秒、首次请求 1 秒的实现，可按当前步骤只产生 1 秒的请求测量；另列 T_setup 的成本公式不能自动恢复冷启动目标的完整时间链。",
      "blocking": true,
      "required_revision": "为冷启动目标声明起止事件，在实例建立或目标加载之前启动相应计时，并明确加载、首次准备与首次请求如何进入冷启动估计量。稳定态窗口可继续从 READY 后开始；若仅研究已加载实例的冷执行，则明确收窄目标，并将加载时间作为独立启动指标交付。用一条包含非零加载时间的设定轨迹核对该边界。"
    },
    {
      "id": "K-WORK-004-R1-T-INTERVAL-CONDITIONS",
      "criterion": "legality",
      "evidence": "“在独立区组、差值近似独立同分布且无 carryover 的条件下，平均差值的区间可写成”之后直接给出“$mean(D) ± t_{1-α/2,n-1}·s_D/√n$”，并使用 16 个独立区组演算。这里没有说明差值正态性或学生化均值近似有效的条件。",
      "impact": "独立同分布本身不能保证小样本 t 区间具有声明覆盖率。反例：差值以 0.99 概率为 −2 ms、以 0.01 概率为 98 ms，总体均值为 −1 ms，方差有限且可无 carryover。16 次全为 −2 的概率约 85.15%，此时样本标准差为零，所给区间为 [−2,−2]，不覆盖总体均值；覆盖率至多约 14.85%。",
      "blocking": true,
      "required_revision": "区分正态独立差值下的精确 t 区间与满足相应矩和样本规模条件时的近似区间，声明 n≥2、置信水平和有限方差等适用前提；明确 16 区组算例仅核对代数，不保证偏态或稀有长尾数据的覆盖率。遇到近似依据不足时保留未决或重新设计有效重复，不能仅凭 iid 标签套用区间。"
    }
  ],
  "limitations": [
    "没有目标 GPU、真实服务、GenAI-Perf、torch.profiler 或 Nsight Compute 的运行证据；采集扰动、缓存、功率漂移和设备性能保持未测边界。",
    "S-NCU 和 S-STATS 原文仅按所供摘录核对，不代表通读完整指南或论文；没有读取源码归档或核验其实现。",
    "所供 profiler.md 是文档生成指令页，不包含展开后的 API 说明；schedule 和张量引用机制主要依据完整来源说明，不能称为独立核验了展开后的上游 API 文档。",
    "非平衡重复、配对层级 bootstrap、任意非平稳 p99、强自相关和序贯推断没有获得一般有效性证明；正文对此声明的范围可以保留。",
    "未独立访问磁盘原文件、reader.html、来源复核记录或验证链接可达性；文档身份绑定使用任务提供的哈希，未声称重新计算磁盘哈希。",
    "未执行 Agent 使用效果或知识版本对照实验，不能据内容审查及离线检查声称构建能力或性能改善。"
  ],
